query ListCollaborationRootHistory {
  listCollaborationRootHistory {
    __typename
    ... on AgentOrgRootHistoryObject {
      root_subject_kind
      root_run_id
      created_at
      archived_at
      is_active
      summary
      org
      closed_task_executions
      __typename
    }
    ... on AgentTeamRootHistoryObject {
      root_subject_kind
      root_run_id
      __typename
    }
  }
}

mutation CreateAgentOrgDefinition($input: CreateAgentOrgDefinitionInput!) {
  createAgentOrgDefinition(input: $input) {
    ...AgentOrgDefinitionFields
    __typename
  }
}

fragment AgentOrgDefinitionFields on AgentOrgDefinition {
  id
  name
  description
  instructions
  category
  avatarUrl
  revision
  handoffs {
    from
    to
    rules
    __typename
  }
  members {
    memberName
    ref
    refType
    refScope
    __typename
  }
  defaultLaunchConfig {
    llmModelIdentifier
    runtimeKind
    llmConfig
    __typename
  }
  loadIssues {
    kind
    definitionId
    name
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    __typename
  }
  __typename
}

query GetDefinitionProblems($kind: DefinitionKind!) {
  definitionProblems(kind: $kind) {
    kind
    definitionId
    code
    reason
    definitionPath
    packageRoot
    usingLastGood
    dependencyChain
    __typename
  }
}

